def replace_words_brute(dictionary, sentence):
    def shortest_root(word):
        best = None
        for root in dictionary:                          # check EVERY root, every word
            if word.startswith(root) and (best is None or len(root) < len(best)):
                best = root
        return best if best else word
    return ' '.join(shortest_root(w) for w in sentence.split())

