import java.util.*;

class TrieNode {
    Map<Character, TrieNode> children = new HashMap<>();
    boolean isEnd = false;
}

public class Main {
    static String replaceWords(List<String> dictionary, String sentence) {
        TrieNode root = new TrieNode();
        for (String word : dictionary) {                        // build the trie ONCE
            TrieNode node = root;
            for (char c : word.toCharArray()) node = node.children.computeIfAbsent(c, k -> new TrieNode());
            node.isEnd = true;
        }
        StringBuilder result = new StringBuilder();
        for (String w : sentence.split(" ")) {
            TrieNode node = root;
            String replacement = w;
            for (int i = 0; i < w.length(); i++) {
                char c = w.charAt(i);
                if (!node.children.containsKey(c)) break;             // no matching root
                node = node.children.get(c);
                if (node.isEnd) { replacement = w.substring(0, i + 1); break; }  // shortest match, stop
            }
            if (result.length() > 0) result.append(' ');
            result.append(replacement);
        }
        return result.toString();
    }
}

