#include <bits/stdc++.h>
using namespace std;

struct TrieNode { unordered_map<char, TrieNode*> children; bool isEnd = false; };

string replaceWords(vector<string>& dictionary, string sentence) {
    TrieNode* root = new TrieNode();
    for (auto& word : dictionary) {                                 // build the trie ONCE
        TrieNode* node = root;
        for (char c : word) {
            if (!node->children.count(c)) node->children[c] = new TrieNode();
            node = node->children[c];
        }
        node->isEnd = true;
    }
    stringstream ss(sentence);
    string w, result;
    while (ss >> w) {
        TrieNode* node = root;
        string replacement = w;
        for (int i = 0; i < (int)w.size(); i++) {
            if (!node->children.count(w[i])) break;                     // no matching root
            node = node->children[w[i]];
            if (node->isEnd) { replacement = w.substr(0, i + 1); break; }   // shortest match, stop
        }
        if (!result.empty()) result += ' ';
        result += replacement;
    }
    return result;
}
